#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

typedef struct Edge {
    int to, next;
} Edge;

static int maxN;
static Edge *redE, *blueE;
static int *redHead, *blueHead;
static int redCnt = 0, blueCnt = 0;

static int *parentR, *depthR, *subR, *heavyR, *headR, *posR, *revPosR;
static int *parentB, *depthB, *subB, *heavyB, *headB, *posB, *revPosB;
static int curPosR = 0, curPosB = 0;

static int *queueArr;

/* ---------- Graph ---------- */

static void addRed(int u, int v) {
    redE[redCnt].to = v; redE[redCnt].next = redHead[u]; redHead[u] = redCnt++;
    redE[redCnt].to = u; redE[redCnt].next = redHead[v]; redHead[v] = redCnt++;
}
static void addBlue(int u, int v) {
    blueE[blueCnt].to = v; blueE[blueCnt].next = blueHead[u]; blueHead[u] = blueCnt++;
    blueE[blueCnt].to = u; blueE[blueCnt].next = blueHead[v]; blueHead[v] = blueCnt++;
}

/* ---------- HLD for Red Tree ---------- */

static void buildRed(int n, int root) {
    int *order = (int*)malloc((n + 5) * sizeof(int));
    int qh = 0, qt = 0;
    queueArr[qt++] = root;
    parentR[root] = 0;
    depthR[root] = 0;

    while (qh < qt) {
        int u = queueArr[qh++];
        order[qh - 1] = u;
        for (int e = redHead[u]; e != -1; e = redE[e].next) {
            int v = redE[e].to;
            if (v == parentR[u]) continue;
            parentR[v] = u;
            depthR[v] = depthR[u] + 1;
            queueArr[qt++] = v;
        }
    }

    for (int i = qt - 1; i >= 0; --i) {
        int u = order[i];
        subR[u] = 1;
        heavyR[u] = -1;
        int best = 0;
        for (int e = redHead[u]; e != -1; e = redE[e].next) {
            int v = redE[e].to;
            if (v == parentR[u]) continue;
            subR[u] += subR[v];
            if (subR[v] > best) {
                best = subR[v];
                heavyR[u] = v;
            }
        }
    }

    curPosR = 0;
    int *stackU = (int*)malloc((n + 5) * sizeof(int));
    int *stackH = (int*)malloc((n + 5) * sizeof(int));
    int top = 0;
    stackU[top] = root;
    stackH[top] = root;
    top++;

    while (top) {
        --top;
        int start = stackU[top];
        int h = stackH[top];
        int u = start;
        while (u != -1) {
            headR[u] = h;
            posR[u] = ++curPosR;
            revPosR[curPosR] = u;

            for (int e = redHead[u]; e != -1; e = redE[e].next) {
                int v = redE[e].to;
                if (v == parentR[u] || v == heavyR[u]) continue;
                stackU[top] = v;
                stackH[top] = v;
                top++;
            }
            u = heavyR[u];
        }
    }

    free(order);
    free(stackU);
    free(stackH);
}

static int lcaRed(int a, int b) {
    while (headR[a] != headR[b]) {
        if (depthR[headR[a]] > depthR[headR[b]]) a = parentR[headR[a]];
        else b = parentR[headR[b]];
    }
    return depthR[a] < depthR[b] ? a : b;
}

static int distRed(int a, int b) {
    int l = lcaRed(a, b);
    return depthR[a] + depthR[b] - 2 * depthR[l];
}

static int kthOnPathRed(int a, int b, int k) {
    int l = lcaRed(a, b);
    int da = depthR[a] - depthR[l];
    int db = depthR[b] - depthR[l];
    if (k <= da) {
        int x = a;
        while (1) {
            int h = headR[x];
            int len = depthR[x] - depthR[h];
            if (k <= len) return revPosR[posR[x] - k];
            k -= len + 1;
            x = parentR[h];
        }
    } else {
        int rem = da + db - k;
        int x = b;
        while (1) {
            int h = headR[x];
            int len = depthR[x] - depthR[h];
            if (rem <= len) return revPosR[posR[x] - rem];
            rem -= len + 1;
            x = parentR[h];
        }
    }
}

