/*
State transition:
Current positions (s, t).
Sigma moves one step along red shortest path from s to t:
  s' = next vertex from s toward t in red tree, unless s==t.
Then if s'==t, game ends.
Sugim moves one step along blue shortest path from t to s' :
  t' = next vertex from t toward s' in blue tree, unless t==s'.
Then if s'==t', game ends.

Potential function:
D = distRed(s,t) + distBlue(s,t)
Each non-terminal full turn decreases D by at least 1.
Thus finite iff eventually meet; because state space finite and D strictly decreases until meeting, impossible to cycle.
Total turns can be simulated directly in O(answer log N), but answer may be large?
Actually each turn decreases D by at least 1, initial D <= 2N, so O(N log N) is fine.
*/

int main(void) {
    int N, X, Y;
    if (scanf("%d %d %d", &N, &X, &Y) != 3) return 0;

    maxN = N + 5;
    redHead = (int*)malloc((maxN) * sizeof(int));
    blueHead = (int*)malloc((maxN) * sizeof(int));
    for (int i = 0; i < maxN; ++i) redHead[i] = blueHead[i] = -1;

    redE = (Edge*)malloc((2 * (N - 1) + 5) * sizeof(Edge));
    blueE = (Edge*)malloc((2 * (N - 1) + 5) * sizeof(Edge));

    for (int i = 0; i < N - 1; ++i) {
        int u, v;
        scanf("%d %d", &u, &v);
        addRed(u, v);
    }
    for (int i = 0; i < N - 1; ++i) {
        int u, v;
        scanf("%d %d", &u, &v);
        addBlue(u, v);
    }

    parentR = (int*)calloc(maxN, sizeof(int));
    depthR  = (int*)calloc(maxN, sizeof(int));
    subR    = (int*)calloc(maxN, sizeof(int));
    heavyR  = (int*)calloc(maxN, sizeof(int));
    headR   = (int*)calloc(maxN, sizeof(int));
    posR    = (int*)calloc(maxN, sizeof(int));
    revPosR = (int*)calloc(maxN, sizeof(int));

    parentB = (int*)calloc(maxN, sizeof(int));
    depthB  = (int*)calloc(maxN, sizeof(int));
    subB    = (int*)calloc(maxN, sizeof(int));
    heavyB  = (int*)calloc(maxN, sizeof(int));
    headB   = (int*)calloc(maxN, sizeof(int));
    posB    = (int*)calloc(maxN, sizeof(int));
    revPosB = (int*)calloc(maxN, sizeof(int));

    queueArr = (int*)malloc((maxN) * sizeof(int));

    buildRed(N, 1);
    buildBlue(N, 1);

    if (X == Y) {
        printf("YES\n0\n");
        return 0;
    }

    ll turns = 0;
    int s = X, t = Y;

    while (1) {
        if (s != t) {
            int d = distRed(s, t);
            s = kthOnPathRed(s, t, 1);
            turns++;
            if (s == t) {
                printf("YES\n%lld\n", turns);
                return 0;
            }
        }

        if (t != s) {
            int d = distBlue(t, s);
            t = kthOnPathBlue(t, s, 1);
            turns++;
            if (s == t) {
                printf("YES\n%lld\n", turns);
                return 0;
            }
        }
    }

    return 0;
}

