public class GameOnGraph {
    static List<Integer>[] redTree, blueTree;
    static int n;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        int X = sc.nextInt() - 1;
        int Y = sc.nextInt() - 1;

        redTree = new ArrayList[n];
        blueTree = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            redTree[i] = new ArrayList<>();
            blueTree[i] = new ArrayList<>();
        }

        for (int i = 0; i < n - 1; i++) {
            int u = sc.nextInt() - 1;
            int v = sc.nextInt() - 1;
            redTree[u].add(v);
            redTree[v].add(u);
        }
        for (int i = 0; i < n - 1; i++) {
            int u = sc.nextInt() - 1;
            int v = sc.nextInt() - 1;
            blueTree[u].add(v);
            blueTree[v].add(u);
        }

        int[] distRed = bfs(redTree, X);
        int[] distBlue = bfs(blueTree, Y);

        int answer = Integer.MAX_VALUE;
        for (int v = 0; v < n; v++) {
            if (distRed[v] != -1 && distBlue[v] != -1) {
                int r = distRed[v];
                int b = distBlue[v];
                if (Math.abs(r - b) <= 1) {
                    answer = Math.min(answer, Math.max(r, b));
                } else if (r < b) {
                    answer = Math.min(answer, b);
                } else {
                    answer = Math.min(answer, r);
                }
            }
        }

        if (answer == Integer.MAX_VALUE) {
            System.out.println(-1);
        } else {
            System.out.println(answer);
        }
    }

    static int[] bfs(List<Integer>[] tree, int start) {
        int[] dist = new int[n];
        Arrays.fill(dist, -1);
        Queue<Integer> q = new LinkedList<>();
        dist[start] = 0;
        q.add(start);
        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : tree[u]) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    q.add(v);
                }
            }
        }
        return dist;
    }
}

