        for(int i=0;i<N-1;i++){int u=sc.nextInt()-1,v=sc.nextInt()-1;blue.get(u).add(v);blue.get(v).add(u);}

        int[][] dist = new int[N*N*2][1];
        int[] ans = new int[N*N*2];
        Arrays.fill(ans,-1);
        int[] childCount = new int[N*N*2];
        Queue<Integer> queue = new LinkedList<>();

        for(int s=0;s<N;s++) for(int t=0;t<2;t++){
            int state=s*N*2+s*2+t;
            ans[state]=0;queue.add(state);
        }
        // BFS retrograde
        // For each state, precompute number of children (moves available)
        for(int s=0;s<N;s++) for(int g=0;g<N;g++) for(int t=0;t<2;t++){
            int state=(s*N+g)*2+t;
            if(t==0) childCount[state]=red.get(s).size();
            else childCount[state]=blue.get(g).size();
        }
        while(!queue.isEmpty()){
            int cur=queue.poll();
            int t=cur%2, g=(cur/2)%N, s=(cur/2)/N;
            int curVal=ans[cur];
            // find predecessors
            if(t==1){// current turn=1(sugim), predecessor turn=0(sigma), sigma moved to s
                for(int ps:red.get(s)){
                    int prev=(ps*N+g)*2+0;
                    if(ans[prev]!=-1) continue;
                    // sigma is minimizer: if any successor is known, take min
                    childCount[prev]--;
                    if(ans[prev]==-1){ans[prev]=curVal+1;queue.add(prev);}
                }
            } else {// current turn=0(sigma), predecessor turn=1(sugim), sugim moved to g
                for(int pg:blue.get(g)){
                    int prev=(s*N+pg)*2+1;
                    if(ans[prev]!=-1) continue;
                    childCount[prev]--;
                    if(childCount[prev]==0){ans[prev]=curVal+1;queue.add(prev);}
                }
            }
        }
        int startState=(X*N+Y)*2+0;
        if(ans[startState]==-1) System.out.println("INFINITE");
        else System.out.println(ans[startState]);
    }
}

