    q.push(X);
    distRed[X] = 0;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int v : red[u]) {
            if (distRed[v] == -1) {
                distRed[v] = distRed[u] + 1;
                q.push(v);
            }
        }
    }

    vector<int> distBlue(N, -1);
    q.push(Y);
    distBlue[Y] = 0;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int v : blue[u]) {
            if (distBlue[v] == -1) {
                distBlue[v] = distBlue[u] + 1;
                q.push(v);
            }
        }
    }

    int ans = INT_MAX;
    for (int i = 0; i < N; i++) {
        if (distRed[i] != -1 && distBlue[i] != -1) {
            if (distRed[i] == distBlue[i]) {
                ans = min(ans, distRed[i] * 2);
            }
            // also possible that they meet after one stays:
            // Sigma arrives earlier and waits: then distRed[i] < distBlue[i]
            // Sugim arrives earlier and waits: then distBlue[i] < distRed[i]
            // The total turns = 2 * max(distRed[i], distBlue[i]) if one waits,
            // but careful: if one waits, it counts as a turn for them.
            // Actually, if Sigma arrives first, on his next turn he stays,
            // which adds extra turns. So total = 2 * max(distRed[i], distBlue[i])
            // but if distRed[i] == distBlue[i], it's 2*distRed[i].
            // For unequal, the larger one determines total turns because
            // the other player can just stay until they meet.
            if (distRed[i] < distBlue[i]) {
                // Sigma arrives earlier, waits
                ans = min(ans, 2 * distBlue[i]);
            } else if (distBlue[i] < distRed[i]) {
                ans = min(ans, 2 * distRed[i]);
            }
        }
    }

    if (ans == INT_MAX) {
        cout << -1 << "\n";
    } else {
        cout << ans << "\n";
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

vector<int> red_tree[100005], blue_tree[100005];

int next_step(vector<int> tree[], int src, int dst, int N) {
    if (src == dst) return src;
    // BFS to find parent in path
    vector<int> par(N+1, -1);
    queue<int> q;
    q.push(src);
    par[src] = src;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int v : tree[u]) {
            if (par[v] == -1) { par[v] = u; q.push(v); }
        }
    }
    // trace back from dst
    int cur = dst;
    while (par[cur] != src) cur = par[cur];
    return cur;
}

