#include <bits/stdc++.h>
using namespace std;

using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, X, Y;
    cin >> N >> X >> Y;
    --X; --Y;

    vector<vector<int>> red(N), blue(N);

    for (int i = 0; i < N - 1; ++i) {
        int a, b;
        cin >> a >> b;
        --a; --b;
        red[a].push_back(b);
        red[b].push_back(a);
    }
    for (int i = 0; i < N - 1; ++i) {
        int a, b;
        cin >> a >> b;
        --a; --b;
        blue[a].push_back(b);
        blue[b].push_back(a);
    }

    // Parent/depth in red tree rooted at X
    vector<int> parR(N, -1), depthR(N, -1);
    {
        queue<int> q;
        q.push(X);
        depthR[X] = 0;
        while (!q.empty()) {
            int v = q.front(); q.pop();
            for (int to : red[v]) {
                if (depthR[to] != -1) continue;
                depthR[to] = depthR[v] + 1;
                parR[to] = v;
                q.push(to);
            }
        }
    }

    // Parent/depth in blue tree rooted at Y
    vector<int> parB(N, -1), depthB(N, -1);
    {
        queue<int> q;
        q.push(Y);
        depthB[Y] = 0;
        while (!q.empty()) {
            int v = q.front(); q.pop();
            for (int to : blue[v]) {
                if (depthB[to] != -1) continue;
                depthB[to] = depthB[v] + 1;
                parB[to] = v;
                q.push(to);
            }
        }
    }

    // Build functional graph:
    // state v means current common "target" vertex.
    // Next state is parent in red then parent in blue:
    // f(v) = parB[parR[v]], if both exist; otherwise game ends at v.
    vector<int> nxt(N, -1);
    for (int v = 0; v < N; ++v) {
        if (parR[v] != -1 && parB[parR[v]] != -1) {
            nxt[v] = parB[parR[v]];
        }
    }

    // Starting state is the unique intersection of Sigma's red path from X
    // and Sugim's blue path from Y after considering final meeting vertex z.
    // For a candidate meeting vertex z, turns needed are depthR[z] + depthB[z].
    // Finite iff repeated application of "go one step toward X in red,
    // then one step toward Y in blue" from z eventually stops.
    //
    // This happens exactly for vertices not belonging to a directed cycle in nxt.
    // We need all possible meeting vertices z satisfying consistency:
    // Sigma can reach z by red path from X, Sugim can reach z by blue path from Y,
    // always true since both are trees.
    //
    // The actual process ends iff there exists a vertex z minimizing total turns
    // that is not on/leading to an infinite loop. In fact, game dynamics force z
    // to be a fixed point of alternating ancestors; equivalently, z must be in the
    // reverse-reachable set of terminal states in nxt.
    //
    // We compute for each vertex whether iterating nxt ends (-1) or loops.
    vector<int> state(N, 0); // 0=unvisited,1=visiting,2=good(ends),3=bad(loop)
    function<int(int)> dfs = [&](int v) -> int {
        if (state[v] == 1) return state[v] = 3;
        if (state[v] == 2 || state[v] == 3) return state[v];
        state[v] = 1;
        if (nxt[v] == -1) {
            state[v] = 2;
        } else {
            int res = dfs(nxt[v]);
            state[v] = (res == 2 ? 2 : 3);
        }
        return state[v];
    };
    for (int i = 0; i < N; ++i) if (state[i] == 0) dfs(i);

    ll ans = (1LL << 62);
    for (int v = 0; v < N; ++v) {
        if (state[v] == 2) {
            ans = min(ans, (ll)depthR[v] + depthB[v]);
        }
    }

    if (ans == (1LL << 62)) {
        cout << -1 << '\n';
    } else {
        cout << ans << '\n';
    }

    return 0;
}
